(() => {
'use strict';const W=HTWorkflow,esc=W.esc;
const saved=W.read('hetu_symbol_library_v3',null);if(saved)Object.assign(SYMBOL_LIBRARY,saved);
const custom=W.read('hetu_custom_icons_v3',{}),baseIcon=iconSVG;
window.iconSVG=function(name,size,color){return custom[name]?'<img src="'+custom[name].data+'" alt="'+esc(custom[name].name)+'" style="width:'+(size||'1.2em')+';height:'+(size||'1.2em')+';object-fit:contain">':baseIcon(name,size,color);};
function persist(){try{W.write('hetu_symbol_library_v3',SYMBOL_LIBRARY);W.write('hetu_custom_icons_v3',custom);return true;}catch(_){showNotification('','保存失败，请检查浏览器本地存储空间');return false;}}
let selected=new Set(),editing=null;
const shell=document.createElement('div');shell.id='htSymbolModal';shell.className='fixed inset-0 z-50 hidden flex items-center justify-center';shell.style.background='rgba(0,0,0,.4)';shell.innerHTML='<div class="bg-white rounded-xl p-6" style="width:680px;max-height:85vh;overflow:auto"><h3 class="font-semibold text-lg mb-4">符号集</h3><div class="grid grid-cols-2 gap-3"><label class="text-sm">名称<input id="hsName" class="w-full border rounded p-2 mt-1"></label><label class="text-sm">归属<input id="hsProject" class="w-full border rounded p-2 mt-1"></label><label class="text-sm">分类<select id="hsCategory" class="w-full border rounded p-2 mt-1"></select></label><label class="text-sm">范围<select id="hsScope" class="w-full border rounded p-2 mt-1"><option>公共集池</option><option>项目私有集</option></select></label></div><div id="hsIcons" class="flex flex-wrap gap-2 mt-4"></div><div id="hsCount" class="text-sm text-gray-500 mt-3"></div><div class="flex justify-end gap-3 mt-5"><button class="btn btn-default" id="hsCancel">取消</button><button class="btn btn-primary" id="hsSave">保存</button></div></div>';document.body.append(shell);
function render(){const box=document.getElementById('hsIcons');box.innerHTML='';for(const name of new Set(Object.values(SYMBOL_LIBRARY.iconPool).flat())){const b=document.createElement('button');b.type='button';b.title=custom[name]?.name||name;b.style.cssText='width:42px;height:42px;border-radius:5px;display:grid;place-items:center;border:1px solid '+(selected.has(name)?'#005653':'#dce5e9')+';background:'+(selected.has(name)?'#edf6f2':'white');b.innerHTML=iconSVG(name,'22px');b.onclick=()=>{selected.has(name)?selected.delete(name):selected.add(name);render();};box.append(b);}document.getElementById('hsCount').textContent='已选 '+selected.size+' 个图标';}
window.htEditSymbol=function(id,initial){editing=SYMBOL_LIBRARY.spriteSets.find(s=>s.id===id)||null;selected=new Set(editing?.icons||initial||[]);document.getElementById('hsName').value=editing?.name||'';document.getElementById('hsProject').value=editing?.project||'平台';document.getElementById('hsCategory').innerHTML=Object.keys(SYMBOL_LIBRARY.iconPool).map(c=>'<option>'+esc(c)+'</option>').join('');document.getElementById('hsCategory').value=editing?.category||'基础';document.getElementById('hsScope').value=editing?.scope||'项目私有集';render();shell.classList.remove('hidden');};
document.getElementById('hsCancel').onclick=()=>shell.classList.add('hidden');
document.getElementById('hsSave').onclick=()=>{const name=document.getElementById('hsName').value.trim(),project=document.getElementById('hsProject').value.trim();if(!name||!project||!selected.size){showNotification('','请填写名称、归属，并选择图标');return;}if(SYMBOL_LIBRARY.spriteSets.some(s=>s.name===name&&s.id!==editing?.id)){showNotification('','已存在同名符号集');return;}const value={...editing,id:editing?.id||W.id('symbols-'),name,project,category:document.getElementById('hsCategory').value,scope:document.getElementById('hsScope').value,icons:[...selected],status:editing?.status||'草稿'};const i=SYMBOL_LIBRARY.spriteSets.findIndex(s=>s.id===value.id);if(i<0)SYMBOL_LIBRARY.spriteSets.push(value);else SYMBOL_LIBRARY.spriteSets[i]=value;if(!persist())return;shell.classList.add('hidden');document.getElementById('mainContent').innerHTML=renderSymbolLibrary();showNotification('','符号集已保存');};
window.htUploadIcon=function(){const input=document.createElement('input');input.type='file';input.accept='.svg,.png,.jpg,.jpeg';input.onchange=()=>{const file=input.files[0];if(!file)return;if(!/\.(svg|png|jpe?g)$/i.test(file.name)){showNotification('','请选择 SVG、PNG 或 JPG 图标');return;}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const id=W.id('icon-');custom[id]={name:file.name,data:reader.result};(SYMBOL_LIBRARY.iconPool['自定义']||(SYMBOL_LIBRARY.iconPool['自定义']=[])).push(id);if(persist()){document.getElementById('mainContent').innerHTML=renderSymbolLibrary();showNotification('','图标已上传');}};img.onerror=()=>showNotification('','无法识别该图片，请重新选择');img.src=reader.result;};reader.readAsDataURL(file);};input.click();};
const oldCard=renderSpriteSetCard;window.renderSpriteSetCard=s=>oldCard(s).replace(/onclick="showNotification\([^\"]+\)"/,'onclick="htEditSymbol(\''+s.id+'\')"');
const oldPool=renderIconPool;window.renderIconPool=function(){return oldPool().replace(/onclick="showNotification\([^\"]+已选图标 ([^ ]+)[^\"]+\)"/g,(_,name)=>'onclick="htEditSymbol(null,[\''+name+'\'])"').replace(/onclick="showNotification\([^\"]+打开上传图标[^\"]+\)"/,'onclick="htUploadIcon()"');};
const oldLibrary=renderSymbolLibrary;window.renderSymbolLibrary=function(){return oldLibrary().replace(/onclick="showNotification\([^\"]+已打开新建符号集[^\"]+\)"/,'onclick="htEditSymbol()"');};
document.getElementById('mainContent').innerHTML=renderSymbolLibrary();
document.addEventListener('keydown',e=>{if(e.key==='Escape')shell.classList.add('hidden');});
})();
